-- Documents remain first-class; templates are retired. Disposable post-Phase-2 database only.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(26);
select has_table('public','atlas_documents','documents table exists');
select has_table('public','atlas_document_versions','document versions exist');
select has_table('public','atlas_document_activity_log','document activity exists');
select has_trigger('public','atlas_documents','atlas_documents_validate_context','document contexts are validated');
select has_trigger('public','atlas_documents','atlas_documents_audit_row','document changes create evidence and versions');
select has_trigger('public','atlas_documents','atlas_documents_reject_delete','documents reject deletion');
select has_trigger('public','atlas_document_versions','atlas_document_versions_reject_mutation','document versions are immutable');
select has_function('public','transition_atlas_document',array['text','boolean','text','bigint'],'document lifecycle RPC exists');
select ok(not has_function_privilege('anon','public.transition_atlas_document(text,boolean,text,bigint)','execute') and not has_function_privilege('authenticated','public.transition_atlas_document(text,boolean,text,bigint)','execute'),'public roles cannot execute document lifecycle RPC');
select ok(has_function_privilege('service_role','public.transition_atlas_document(text,boolean,text,bigint)','execute'),'service role can execute document lifecycle RPC');
select ok(not has_table_privilege('service_role','public.atlas_document_versions','delete'),'service role cannot delete document versions');
select ok((select bool_and(relrowsecurity) from pg_class where oid in ('public.atlas_documents'::regclass,'public.atlas_document_versions'::regclass,'public.atlas_document_activity_log'::regclass)),'all document tables enforce RLS');
select throws_ok($$insert into public.atlas_documents(id,title,content,context_type,context_id,created_by,updated_by) values('__atlas_bad_cycle_document__','Invalid context','','cycle','missing','codex','codex')$$,'23514',null,'cycle contexts are retired');
select throws_ok($$insert into public.atlas_documents(id,title,content,context_type,context_id,created_by,updated_by) values('__atlas_bad_initiative_document__','Invalid context','','initiative','missing','codex','codex')$$,'23514',null,'initiative contexts are retired');
insert into public.atlas_documents(id,title,content,context_type,status,revision,created_by,updated_by) values('__atlas_document_regression__','Strategy brief','# Strategy','workspace','active',0,'codex','codex');
select is((select count(*) from public.atlas_document_versions where document_id='__atlas_document_regression__'),1::bigint,'creation records the first version');
select lives_ok($$update public.atlas_documents set content='# Revised',revision=1,updated_by='codex',updated_at=timezone('utc',now()) where id='__atlas_document_regression__'$$,'document content can be revisioned');
select is((select count(*) from public.atlas_document_versions where document_id='__atlas_document_regression__'),2::bigint,'edit appends a version');
select is((select content from public.atlas_document_versions where document_id='__atlas_document_regression__' and revision=0),'# Strategy','original version stays readable');
select throws_ok($$update public.atlas_document_versions set content='rewrite' where document_id='__atlas_document_regression__' and revision=0$$,'55000','ATLAS_PROJECT_HISTORY_IMMUTABLE','versions cannot be rewritten');
select lives_ok($$select public.transition_atlas_document('__atlas_document_regression__',false,'codex',1)$$,'document can archive');
select is((select status from public.atlas_documents where id='__atlas_document_regression__'),'archived','archive persists');
select lives_ok($$select public.transition_atlas_document('__atlas_document_regression__',true,'codex',2)$$,'document can restore');
select is((select status from public.atlas_documents where id='__atlas_document_regression__'),'active','restore persists');
select is((select count(*) from public.atlas_document_versions where document_id='__atlas_document_regression__'),4::bigint,'lifecycle transitions are versioned');
select throws_ok($$delete from public.atlas_documents where id='__atlas_document_regression__'$$,'55000','ATLAS_IMMUTABLE_HISTORY','documents cannot be physically deleted');
select ok((select count(*)>=4 from public.atlas_document_activity_log where document_id='__atlas_document_regression__'),'activity captures creation edit archive restore');
select * from finish();
rollback;
